<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:Arial,sans-serif;font-size:10pt;color:#24364b}table{width:100%;border-collapse:collapse;margin-bottom:14px}td,th{border:1px solid #dbe5ed;padding:6px;vertical-align:top}th{background:#eaf6ff;color:#176eaf;text-align:left}.no-border td{border:0}.label{font-size:8pt;color:#718096;text-transform:uppercase}.right{text-align:right}.total{font-size:12pt;color:#188ae2;font-weight:bold}</style></head><body>
<table class="no-border"><tr><td><h2 style="color:#188ae2;margin:0">ORDEN DE COMPRA DIRECTA</h2><strong>{{ $directPurchaseOrder->folio }}</strong></td><td class="right"><strong>{{ $company?->legal_name ?? $company?->name ?? 'TotalGas' }}</strong><br><span class="label">RFC</span> {{ $company?->rfc ?? '—' }}<br>Emisión: {{ optional($directPurchaseOrder->issued_at)->format('d/m/Y H:i') }}</td></tr></table>
<table><tr><th>Proveedor</th><th>Entrega y control</th></tr><tr><td><strong>{{ $directPurchaseOrder->supplier?->company_name }}</strong><br><span class="label">RFC</span> {{ $directPurchaseOrder->supplier?->rfc ?? '—' }}<br><span class="label">Contacto</span> {{ $directPurchaseOrder->supplier?->contact_person ?? '—' }}</td><td><span class="label">Ubicación de recepción</span><br>{{ $directPurchaseOrder->receivingLocation?->name ?? '—' }}<br><span class="label">Solicitó</span><br>{{ $directPurchaseOrder->creator?->name ?? '—' }}</td></tr></table>
