<table class="no-border"><tr><td style="width:60%"><span class="label">Justificación</span><br>{{ $directPurchaseOrder->justification }}</td><td class="right"><div>Subtotal: ${{ number_format((float)$directPurchaseOrder->subtotal,2) }}</div><div>IVA: ${{ number_format((float)$directPurchaseOrder->iva_amount,2) }}</div><div class="total">Total: ${{ number_format((float)$directPurchaseOrder->total,2) }} {{ $directPurchaseOrder->currency }}</div></td></tr></table>
